import { useState } from 'react'
import { Link } from 'react-router-dom'
import { api } from '../api.js'
import { TEMAS } from '../temas.js'
import Cenario from './Cenario.jsx'
import Logo from './Logo.jsx'
import Icone from './Icones.jsx'
import TurmaAnimada from './TurmaAnimada.jsx'

// Cartão de login sobre o cenário, com os personagens dos temas no chão.
// As abas de perfil só mudam o texto e a conta de demonstração: quem decide a área
// é o perfil salvo no servidor.
const PERFIS = [
  { id: 'escola', rotulo: 'Escola', frase: 'Envie o PDI e aprove os jogos', icone: 'escola', cor: 'verde', email: 'escola@demo.com' },
  { id: 'familia', rotulo: 'Família', frase: 'Acompanhe o plano e o progresso', icone: 'familia', cor: 'rubi', email: 'familia@demo.com' },
  { id: 'crianca', rotulo: 'Criança', frase: 'Jogue e ganhe itens', icone: 'crianca', cor: 'pessego', email: 'ana@demo.com' },
]

export default function Login({ entrar }) {
  const [perfil, setPerfil] = useState(PERFIS[0])
  const [email, setEmail] = useState('')
  const [senha, setSenha] = useState('')
  const [erro, setErro] = useState('')
  const [enviando, setEnviando] = useState(false)
  const [pausado, setPausado] = useState(false)

  async function enviar(ev) {
    ev.preventDefault()
    setErro('')
    setEnviando(true)
    try {
      const { usuario } = await api('/login', { metodo: 'POST', corpo: { email, senha } })
      entrar(usuario)
    } catch (e) {
      setErro(e.message)
    } finally {
      setEnviando(false)
    }
  }

  function trocarPerfil(p) {
    setPerfil(p)
    setErro('')
  }

  return (
    <main className={`login ${pausado ? 'pausado' : ''}`}>
      <Cenario />
      <Link className="login-voltar" to="/"><Icone nome="voltar" tamanho={20} /> Início</Link>
      <button type="button" className="login-pausa" onClick={() => setPausado(!pausado)} aria-pressed={pausado}>
        <Icone nome={pausado ? 'jogar' : 'pausar'} tamanho={20} /> {pausado ? 'Continuar' : 'Pausar'}
      </button>

      <form className={`login-cartao ${perfil.id === 'crianca' ? 'login-crianca' : ''}`} onSubmit={enviar}>
        <Logo tamanho={52} />
        <p className="login-frase">Do PDI ao jogo, no ritmo de cada criança.</p>

        <div className="abas-perfil" role="radiogroup" aria-label="Quem está entrando?">
          {PERFIS.map((p) => (
            <button
              key={p.id}
              type="button"
              role="radio"
              aria-checked={perfil.id === p.id}
              className={`aba-perfil perfil-${p.cor}`}
              onClick={() => trocarPerfil(p)}
            >
              <Icone nome={p.icone} tamanho={22} /> {p.rotulo}
            </button>
          ))}
        </div>
        <p className="ajuda login-perfil-frase">{perfil.id === 'crianca' ? 'Peça ajuda a um adulto para entrar.' : perfil.frase}.</p>

        <label>
          E-mail
          <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} required autoComplete="username" />
        </label>
        <label>
          Senha
          <input type="password" value={senha} onChange={(e) => setSenha(e.target.value)} required autoComplete="current-password" />
        </label>
        {erro && <p className="erro" role="alert">{erro}</p>}
        <button className="primario" disabled={enviando}>{enviando ? 'Entrando…' : `Entrar como ${perfil.rotulo.toLowerCase()}`}</button>

        <div className="demo">
          <p>Para testar, use a conta de demonstração (senha <code>demo</code>).</p>
          <button type="button" className={`demo-${perfil.cor}`} onClick={() => { setEmail(perfil.email); setSenha('demo') }}>
            Preencher conta de {perfil.rotulo.toLowerCase()}
          </button>
        </div>
      </form>

      <TurmaAnimada temas={TEMAS} />
    </main>
  )
}

// Ponto único de integração entre o site e os jogos, que moram em hub/src/jogos (alias @hub).
// O contrato (manifesto.js + montar()) está em hub/src/jogos/contrato.js.
import { JOGOS, jogoPorId } from '@hub/jogos/registro.js'
import { HIPERFOCOS } from '@hub/compartilhado/temas.js'

// O site usa os mesmos temas do hub (temas.js). Aluno sem tema ou com um id antigo cai no primeiro.
export const temaDoHub = (temaId) => HIPERFOCOS.find((h) => h.id === temaId) ?? HIPERFOCOS[0]

export const jogoDoHub = jogoPorId

// Ids dos jogos que existem no hub, para conferir com o catálogo do servidor.
export const idsDosJogos = () => JOGOS.map((j) => j.id)

// Opções iguais para todos os jogos. Som baixo e música desligada por padrão (DESIGN.md, regra 7).
export const opcoesDosJogos = () => ({
  sons: true,
  musica: false,
  reduzirMovimento: matchMedia('(prefers-reduced-motion: reduce)').matches,
})

// Carrega o jogo e o monta dentro de `elemento`. Devolve a função desmontar().
export async function abrirJogo(elemento, { jogo, tema, nivel, opcoes, aoTerminar, aoSair }) {
  const { montar } = await jogo.carregar()
  return montar(elemento, { tema, nivel, opcoes, aoTerminar, aoSair })
}

// Resultado que o site envia ao servidor. `resultado` vem do jogo:
// { status: 'completed' | 'abandoned', attempts, correct, hints }.
export function paraServidor(jogoId, resultado) {
  const { status, attempts = 0, correct = 0, hints = 0 } = resultado
  return { jogoId, status, attempts, correct, hints }
}

// Abre um jogo sem o hub, para quem está desenvolvendo ele: jogo.html?id=memoria&tema=trem
// Os resultados aparecem no console do navegador.
import '@fontsource/fredoka/400.css'
import { HIPERFOCOS } from './compartilhado/temas.js'
import { JOGOS, jogoPorId } from './jogos/registro.js'

const params = new URLSearchParams(location.search)
const jogo = jogoPorId(params.get('id'))
const tema = HIPERFOCOS.find((h) => h.id === params.get('tema')) ?? HIPERFOCOS[0]
const raiz = document.getElementById('raiz')
document.body.style.margin = '0'

if (!jogo) {
  raiz.innerHTML = `<p style="font: 18px system-ui; padding: 16px">Escolha um jogo: ${JOGOS.map(
    (j) => `<a href="?id=${j.id}">${j.id}</a>`,
  ).join(' · ')}</p>`
} else {
  raiz.style.cssText = 'position: fixed; inset: 0; overflow: auto'
  const { montar } = await jogo.carregar()
  const desmontar = montar(raiz, {
    tema,
    nivel: Number(params.get('nivel')) || 1,
    opcoes: { sons: params.get('sons') !== '0', musica: params.get('musica') === '1', reduzirMovimento: params.get('rm') === '1' },
    aoTerminar: (resultado) => console.info('[jogo] resultado', resultado),
    aoSair: () => {
      desmontar()
      raiz.innerHTML = '<p style="font: 18px system-ui; padding: 16px">O jogo pediu para sair. <a href="">Abrir de novo</a></p>'
    },
  })
  window.__desmontar = desmontar
}

