    q(db.from('resultados').select('jogo_id, status, attempts, correct, hints, criado_em').eq('aluno_id', alunoId).order('criado_em')),
  ])
  const nome = (id) => HABILIDADES.find((h) => h.id === id)?.nome ?? id
  res.json({
